{"implementation":"def solve(case):
    def fail(message):
        raise ValueError(message)

    if not isinstance(case, dict):
        fail("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        fail("payload must be an object")

    if "nodes" not in payload:
        fail("missing required field: nodes")
    if "required_symbols" not in payload:
        fail("missing required field: required_symbols")

    nodes = payload["nodes"]
    required_symbols = payload["required_symbols"]

    if not isinstance(nodes, list):
        fail("nodes must be a list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        fail("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    root_ids = []

    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            fail("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                fail("missing required node field: " + field)

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id == "":
            fail("node id must be a non-empty string")
        if node_id in by_id:
            fail("duplicate node id: " + node_id)
        if parent is not None and not isinstance(parent, str):
            fail("node parent must be null or a string")
        if not isinstance(symbol, str) or symbol == "":
            fail("node symbol must be a non-empty string")
        if not isinstance(depth, int) or depth < 0:
            fail("node depth must be a non-negative integer")
        if not isinstance(removable, bool):
            fail("node removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            fail("node utility must be numeric")

        by_id[node_id] = {
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
            "utility": utility,
            "index": index,
        }
        if parent is None:
            root_ids.append(node_id)

    if len(root_ids) != 1:
        fail("tree must contain exactly one root")

    root_id = root_ids[0]
    if by_id[root_id]["depth"] != 0:
        fail("root depth must be 0")

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            fail("node parent does not exist: " + parent)
        if by_id[parent]["depth"] >= node["depth"]:
            fail("child depth must be greater than parent depth")
        children[parent].append(node_id)

    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            fail("cycle detected in tree")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(by_id):
        fail("all nodes must be reachable from root")

    retained = set(by_id)
    removal_order = []

    def required_symbols_remain(candidate_retained):
        represented = {by_id[node_id]["symbol"] for node_id in candidate_retained}
        return required.issubset(represented)

    if not required_symbols_remain(retained):
        fail("initial tree does not represent all required symbols")

    candidate_order = sorted(by_id.values(), key=lambda node: (-node["depth"], node["id"]))

    for node in candidate_order:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        tentative = set(retained)
        tentative.remove(node_id)
        if not required_symbols_remain(tentative):
            continue

        retained = tentative
        removal_order.append(node_id)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
        "grammar_valid": True,
        "interestingness_preserved": required_symbols_remain(retained),
        "registered_candidate_order": [node["id"] for node in candidate_order],
        "stable_ties": True,
    }
"}
